SELECT COUNT(id) FROM kujiale_designer_works
AND design_name LIKE CONCAT('%', #{designNameLike}, '%')
AND design_id = #{designIdEq}

SELECT id, design_name, cover_pic, is_origin, is_excellent, is_real_excellent, is_top, design_id, plan_id, comm_name, city, name, tag_id, design_pano_url, user_avatar, email, user_name, user_id, organization_id, created, updated, view_count, like_count, ku_created FROM kujiale_designer_works
AND design_name LIKE CONCAT('%', #{designNameLike}, '%')
AND design_id = #{designIdEq}
ORDER BY created DESC
LIMIT #{limit} OFFSET #{offset}
